from audit_excessive_permissions import audit_excessive_permissions


def _finding(ident, desc, path, text, line, column, feature, annotation, severity, confidence="High", endline=None, endcol=None, route=None, feature_kind="Normal"):
    lines = text.splitlines(True)
    start = sum(len(x) for x in lines[:line-1]) + column
    endline = endline or line
    endcol = (len(lines[endline-1].rstrip('\r\n')) if endline <= len(lines) else column+len(feature)) if endcol is None else endcol
    end = sum(len(x) for x in lines[:endline-1]) + endcol
    route = route or []
    return {"ident":ident,"desc":desc,"url":"https://docs.zizmor.sh/audits/#"+ident,
      "determinations":{"confidence":confidence,"severity":severity,"persona":"Regular"},
      "locations":[{"symbolic":{"key":{"Local":{"prefix":None,"given_path":path}},"annotation":annotation,"route":{"route":route},"feature_kind":feature_kind,"kind":"Primary"},
      "concrete":{"location":{"start_point":{"row":line-1,"column":column},"end_point":{"row":endline-1,"column":endcol},"offset_span":{"start":start,"end":end}},"feature":feature,"comments":[]}}],"ignored":False}


def audit(record, persona, config=None):
