@dataclass
class Input:
    path: str
    kind: str
    text: str


def classify(path: str, text: str, infer: bool = True) -> str | None:
    name = Path(path).name.lower()
    normalized = '/' + path.replace('\\', '/').lstrip('/')
    if name in ('dependabot.yml', 'dependabot.yaml') or '.github/dependabot.' in path.replace('\\', '/'):
        return 'dependabot'
    if name in ('action.yml', 'action.yaml'):
        return 'actions'
    if '/.github/workflows/' in normalized:
        return 'workflows'
    if not infer:
        return None
    if re.search(r'(?m)^\s*(?:on|jobs)\s*:', text):
        return 'workflows'
    if re.search(r'(?m)^\s*(?:runs|inputs|outputs)\s*:', text):
        return 'actions'
    if re.search(r'(?m)^\s*updates\s*:', text):
        return 'dependabot'
    return None


def _ignored(rel: str, rules: list[tuple[str, str]]) -> bool:
    ignored = False
    for base, line in rules:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('\\#') or line.startswith('\\!'):
            line = line[1:]
        negate = line.startswith('!')
        pat = line[1:] if negate else line
        pat = pat.rstrip('/')
        sub = rel[len(base):].lstrip('/') if base and rel.startswith(base + '/') else ('' if rel == base else None)
        if sub is None:
